/**
 * Property-based test for DslPreviewPanel confidence bar.
 *
 * Feature: sprint-26-nl-search
 * **Property 11: `DslPreviewPanel` confidence bar `data-band` matches `ConfidenceBandThresholds`**
 * **Validates: Requirements 10.1, 10.2, 10.3**
 *
 * For c ∈ [0, 1] generated by fast-check:
 *   1. data-band === 'high'   when c >= 0.75
 *   2. data-band === 'medium' when 0.4 <= c < 0.75
 *   3. data-band === 'low'    when c < 0.4
 *   4. Fill element inline `width` equals `${clamp(0,c,1) * 100}%`
 *   5. No other data-band value ever appears
 *
 * Minimum iterations: 100
 */

import { render } from '@testing-library/react';
import * as fc from 'fast-check';
import { describe, test, expect, vi } from 'vitest';

import { DslPreviewPanel } from '../DslPreviewPanel';

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

/**
 * Monaco editor is lazily loaded via React.lazy / Suspense.
 * Mock it so tests resolve synchronously without a real editor bundle.
 */
vi.mock('@monaco-editor/react', () => ({
  default: () => <div data-testid="monaco-mock" />,
}));

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Render DslPreviewPanel with a given confidence value and return the
 * [data-band] element and its first styled child (the fill bar).
 */
function renderAndGetBar(confidence: number): {
  bandElement: Element | null;
  band: string | null;
  fillWidth: string | null;
  unmount: () => void;
} {
  const { container, unmount } = render(
    <DslPreviewPanel
      dsl="{}"
      explanation=""
      confidence={confidence}
      onExecute={() => undefined}
      onSaveAsFilter={() => undefined}
    />,
  );

  const bandElement = container.querySelector('[data-band]');
  const band = bandElement?.getAttribute('data-band') ?? null;
  const fillElement = bandElement?.querySelector<HTMLElement>('[style]') ?? null;
  const fillWidth = fillElement?.style.width ?? null;

  return { bandElement, band, fillWidth, unmount };
}

// ---------------------------------------------------------------------------
// Property 11 — data-band matches ConfidenceBandThresholds for all c ∈ [0, 1]
// ---------------------------------------------------------------------------

describe('Feature: sprint-26-nl-search, Property 11: DslPreviewPanel confidence bar data-band', () => {
  test(
    'data-band is high/medium/low matching thresholds and fill width equals c*100% for all c in [0, 1]',
    () => {
      fc.assert(
        fc.property(
          fc.double({ min: 0, max: 1, noNaN: true }),
          (c) => {
            const { band, fillWidth, unmount } = renderAndGetBar(c);

            // ----- Property 5: band must be one of the three valid values -----
            expect(['high', 'medium', 'low']).toContain(band);

            // ----- Properties 1–3: band matches thresholds -----
            if (c >= 0.75) {
              expect(band).toBe('high');
            } else if (c >= 0.4) {
              expect(band).toBe('medium');
            } else {
              expect(band).toBe('low');
            }

            // ----- Property 4: fill width equals clamp(0,c,1)*100% -----
            const clampedPercent = `${Math.max(0, Math.min(1, c)) * 100}%`;
            expect(fillWidth).toBe(clampedPercent);

            unmount();
          },
        ),
        { numRuns: 100, endOnFailure: true },
      );
    },
  );

  test(
    'data-band is exactly "high" for all c >= 0.75',
    () => {
      fc.assert(
        fc.property(
          fc.double({ min: 0.75, max: 1, noNaN: true }),
          (c) => {
            const { band, unmount } = renderAndGetBar(c);
            expect(band).toBe('high');
            unmount();
          },
        ),
        { numRuns: 50, endOnFailure: true },
      );
    },
  );

  test(
    'data-band is exactly "medium" for all 0.4 <= c < 0.75',
    () => {
      fc.assert(
        fc.property(
          fc.double({ min: 0.4, max: 0.74999999, noNaN: true }),
          (c) => {
            const { band, unmount } = renderAndGetBar(c);
            expect(band).toBe('medium');
            unmount();
          },
        ),
        { numRuns: 50, endOnFailure: true },
      );
    },
  );

  test(
    'data-band is exactly "low" for all c < 0.4',
    () => {
      fc.assert(
        fc.property(
          fc.double({ min: 0, max: 0.39999999, noNaN: true }),
          (c) => {
            const { band, unmount } = renderAndGetBar(c);
            expect(band).toBe('low');
            unmount();
          },
        ),
        { numRuns: 50, endOnFailure: true },
      );
    },
  );

  // Boundary / edge case examples
  test('boundary c=0.75 → high', () => {
    const { band, unmount } = renderAndGetBar(0.75);
    expect(band).toBe('high');
    unmount();
  });

  test('boundary c=0.4 → medium', () => {
    const { band, unmount } = renderAndGetBar(0.4);
    expect(band).toBe('medium');
    unmount();
  });

  test('boundary c=0 → low with 0% fill', () => {
    const { band, fillWidth, unmount } = renderAndGetBar(0);
    expect(band).toBe('low');
    expect(fillWidth).toBe('0%');
    unmount();
  });

  test('boundary c=1 → high with 100% fill', () => {
    const { band, fillWidth, unmount } = renderAndGetBar(1);
    expect(band).toBe('high');
    expect(fillWidth).toBe('100%');
    unmount();
  });
});
